// PATCH /api/users/:id
// undefined → do not change
// null → clear value

const updates = {
  name: 'Alice',      // update to 'Alice'
  email: null,        // clear email
  phone: undefined    // don't change phone
}

// Backend handler:
function applyPatch(existing, updates) {
  const result = { ...existing }

  for (const [key, value] of Object.entries(updates)) {
    if (value === undefined) {
      // Skip - don't change
      continue
    }
    if (value === null) {
      // Clear the field
      result[key] = null
    } else {
      // Update the field
      result[key] = value
    }
  }

  return result
}

